```tsx
import { useChangeLanguage, useCurrentScreen } from '@auth0/auth0-acul-react';

const LanguageSelector = () => {
  const changeLanguage = useChangeLanguage();
  const screenOptions = useCurrentScreen();
  const tenant = screenOptions?.tenant;
  const transaction = screenOptions?.transaction;

  const handleChangeLanguage = async (language: string) => {
    try {
      await changeLanguage({ language, persist: 'session' });
    } catch (error) {
      console.error('Failed to change language:', error);
    }
  };

  return (
    <>
      {tenant?.enabledLocales && (
        <div>
          <label htmlFor="language-select">
            Language
          </label>
          <select
            id="language-select"
            onChange={(e) => handleChangeLanguage(e.target.value)}
            defaultValue={transaction?.locale}
          >
            {tenant.enabledLocales.map((locale: string) => (
              <option key={locale} value={locale}>
                {locale.toUpperCase()}
              </option>
            ))}
          </select>
        </div>
      )}
    </>
  );
};
```

```tsx
import { useCurrentScreen } from '@auth0/auth0-acul-react';

const AuthFlow = () => {
  const screenOptions = useCurrentScreen();
  const screen = screenOptions?.screen?.name || "login-id";

  switch (screen) {
    case "login-id":
      return <LoginIdScreen />;
    case "login-password":
      return <LoginPasswordScreen />;
    case "mfa-otp-challenge":
      return <MfaOtpChallengeScreen />;
    default:
      return null;
  }
};
```

```tsx
import { useCurrentScreen } from '@auth0/auth0-acul-react';

const CustomAuthScreen = () => {
  const screenOptions = useCurrentScreen();
  const organizationId = screenOptions?.organization?.id;
  const errors = screenOptions?.transaction?.errors || [];
  const locale = screenOptions?.transaction?.locale || 'en';

  return (
    <div>
      {organizationId && <p>Organization: {organizationId}</p>}
      {errors.map((error, i) => (
        <p key={i} className="error">{error.message}</p>
      ))}
      <p>Language: {locale}</p>
    </div>
  );
};
```

